<script setup>
import { ref, computed, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { musclesData } from '@/data/muscles.js'

const router = useRouter()

// --- ЛОГИКА КАРТЫ ---
const defaultData = { name: 'FitAnatomy', category: 'Выберите зону', desc: 'Наведите курсор на интерактивную карту...', exercises: [], color: '#abababfc' }
const activeMuscle = ref({ ...defaultData })
const updateMuscle = (id) => { if (musclesData[id]) activeMuscle.value = musclesData[id] }
const resetMuscle = () => { activeMuscle.value = { ...defaultData } }
const goToLesson = (id) => { router.push(`/theory/${id}`) }

// --- БЕСКОНЕЧНЫЙ СЛАЙДЕР ---
const activeFilter = ref('Все')
const currentIndex = ref(0)
const transitionEnabled = ref(true)

const categories = {
  'Все': Object.keys(musclesData),
  'Верх тела': ['neck', 'back', 'delts', 'biceps', 'triceps', 'forearm'],
  'Торс': ['chest', 'abs', 'back'],
  'Низ тела': ['glutes', 'quadriceps', 'hamstring', 'calves']
}

const baseList = computed(() => {
  return categories[activeFilter.value].map(key => ({ id: key, ...musclesData[key] }))
})

// Тройной список для бесшовности
const infiniteList = computed(() => [...baseList.value, ...baseList.value, ...baseList.value])

// Устанавливаем начальную позицию на середину (на второй набор списка)
onMounted(() => {
  currentIndex.value = baseList.value.length
})

const nextSlide = () => {
  currentIndex.value++
  // Если зашли глубоко в третий набор, прыгаем незаметно во второй
  if (currentIndex.value >= baseList.value.length * 2) {
    setTimeout(() => {
      transitionEnabled.value = false
      currentIndex.value = baseList.value.length
      setTimeout(() => { transitionEnabled.value = true }, 20)
    }, 600)
  }
}

const prevSlide = () => {
  currentIndex.value--
  // Если ушли в первый набор, прыгаем незаметно во второй
  if (currentIndex.value < baseList.value.length) {
    setTimeout(() => {
      transitionEnabled.value = false
      currentIndex.value = baseList.value.length * 2 - 1
      setTimeout(() => { transitionEnabled.value = true }, 20)
    }, 600)
  }
}

const setFilter = (f) => {
  activeFilter.value = f
  currentIndex.value = baseList.value.length // Сброс на середину
}
</script>


