        <div class="info-area">
          <transition name="slide-fade" mode="out-in">
            <div :key="activeMuscle.name" class="muscle-data">
              <span class="m-cat" :style="{ color: activeMuscle.color }">{{ activeMuscle.category }}</span>
              <h2 class="m-name">{{ activeMuscle.name }}</h2>
              <p class="m-desc">{{ activeMuscle.desc }}</p>
              
              <div v-if="activeMuscle.exercises.length" class="m-exercises">
                <p class="ex-label">Базовые упражнения:</p>
                <ul>
                  <li v-for="ex in activeMuscle.exercises" :key="ex">
                    <span class="bullet" :style="{ backgroundColor: activeMuscle.color }"></span>
                    {{ ex }}
                  </li>
                </ul>
              </div>
            </div>
          </transition>
        </div>
      </div>
    </section>

    <!-- БЛОК 2: БИБЛИОТЕКА (ПРЕДЫДУЩИЙ ДИЗАЙН) -->
    <section id="lessons" class="lessons-section">
      <div class="section-header">
        <h2>Основы теории</h2>
        <div class="filters">
          <button v-for="f in Object.keys(categories)" :key="f" 
                  :class="{ active: activeFilter === f }" @click="setFilter(f)">
            {{ f }}
          </button>
        </div>
      </div>

      <div class="slider-container">
        <!-- Те самые стрелочки по бокам в пустом пространстве -->
        <button class="nav-arrow left" @click="prevSlide">‹</button>
        
        <div class="slider-viewport">
          <div class="slider-track" 
               :style="{ 
                 transform: `translateX(calc(-${currentIndex} * (50% + 15px)))`,
                 transition: transitionEnabled ? 'transform 0.6s cubic-bezier(0.25, 1, 0.5, 1)' : 'none'
               }">
            <div class="lesson-card" v-for="(lesson, idx) in infiniteList" :key="idx">
              <div class="card-image">
                <img v-if="lesson.image" :src="lesson.image" :alt="lesson.name" class="muscle-img">
              </div>
              <div class="card-body">
                <span class="category">{{ lesson.category }}</span>
                <h3>{{ lesson.name }}</h3>
                <p class="preview-text">{{ lesson.desc.substring(0, 85) }}...</p>
